# Reactivity {.maize}


## Very basic app

::: columns
::: {.column width="50%"}

::: {.cell}

```{.r .cell-code}
# app.R
library(shiny)

ui <- fluidPage(
  headerPanel("basic app"),

  sidebarPanel(

    sliderInput("a", 
      label = "Select an input to display",
      min = 0, max = 100, value = 50)
  ),

  mainPanel(h1(textOutput("text")))
)

server <- function(input, output) {
    output$text <- renderText({
      print(input$a)
    })
}

shinyApp(ui = ui, server = server)
```
:::

